-- Fifty at-home plans for when we're in different cities: on a video call, or sent to each
-- other. All tagged "long-distance", so "feeling long-distance" in the jar draws only these.
-- Costs are rough totals for both of us. A title that's already in the jar is skipped.
WITH new (title, notes, est_cost, duration, tags, energy) AS (VALUES
  ('Press play together on the same movie', 'Count down 3, 2, 1 on a call, or use a watch-party extension. Pause rule: either of you can stop it to talk.', 0, 'short', 'long-distance,cozy,romantic', 'low'),
  ('Cook the same recipe on a video call', 'Pick a recipe, buy the same ingredients in both cities, prop the phones up in the kitchen and cook side by side. Eat together.', 800, 'short', 'long-distance,foodie,cozy', 'med'),
  ('Order each other dinner', 'Each of you secretly orders a delivery to the other''s door. Unbox on call and eat together.', 1500, 'short', 'long-distance,foodie,romantic', 'low'),
  ('Wander a museum online', 'Pick a museum on Google Arts & Culture and walk it together on a shared screen. Each of you chooses one piece to talk about.', 0, 'short', 'long-distance,cultural,chill', 'low'),
  ('Stargaze on a call', 'Lights off, a stargazing app open, find the same star or the moon from both windows.', 0, 'short', 'long-distance,romantic,chill', 'low'),
  ('Co-op game night', 'A two-player online game, like Stardew Valley, or It Takes Two (one copy plus the free Friend''s Pass).', 1000, 'short', 'long-distance,games', 'med'),
  ('Drawing guessing game', 'A free online draw-and-guess game for two. The worse the drawings, the better the night.', 0, 'short', 'long-distance,games,creative', 'med'),
  ('Online chess with stakes', 'Best of three. Whoever loses writes the winner a four-line poem and reads it out.', 0, 'short', 'long-distance,games', 'low'),
  ('Read a book aloud to each other', 'One chapter a night, taking turns. Pick something short and gentle.', 400, 'short', 'long-distance,cozy,romantic', 'low'),
  ('Make up a bedtime story together', 'One sentence each, back and forth, until someone falls asleep or the story gets ridiculous.', 0, 'short', 'long-distance,creative,cozy', 'low'),
  ('Fall asleep on a call', 'Talk until you''re both drowsy, then leave the call on. Old-fashioned and lovely.', 0, 'short', 'long-distance,cozy,romantic', 'low'),
  ('Write "open when" letters', 'Five envelopes each: open when you miss me, when you''re sad, when you can''t sleep… Post them the next day.', 300, 'short', 'long-distance,romantic,creative', 'low'),
  ('Care package swap', 'About ₹1,000 each of small things that remind you of the other. Ship them, then open together on a call.', 2000, 'short', 'long-distance,romantic', 'low'),
  ('Walk your own cities together', 'Both head out on a call, earphones in, same playlist. Describe what you''re seeing as you go.', 0, 'short', 'long-distance,active,chill', 'med'),
  ('Coffee date across cities', 'Make the same coffee or chai at the same time and drink it slowly on a call, like a café table for two.', 200, 'short', 'long-distance,cozy,chill', 'low'),
  ('Plan our next visit, hour by hour', 'Open a shared doc and plan the next time you''re together: where you''ll eat, what you''ll see, and one surprise each.', 0, 'short', 'long-distance,romantic', 'low'),
  ('Design our dream home', 'A shared Pinterest board: one room each, then swap and critique. The kitchen is always a fight.', 0, 'short', 'long-distance,creative,chill', 'low'),
  ('Start a language together', 'Pick a language neither of you speaks, do the first lesson on a call, then keep a streak going.', 0, 'short', 'long-distance,cultural', 'med'),
  ('Take an online class together', 'A one-off live workshop, in watercolour, a cuisine or photography. Both sign up and compare results after.', 1500, 'short', 'long-distance,creative', 'med'),
  ('Paint each other from a screenshot', 'Each takes a screenshot of the other mid-call and paints or sketches it. Reveal at the same time.', 300, 'short', 'long-distance,creative,romantic', 'low'),
  ('Workout together on a call', 'Same YouTube workout, phones propped up. No one is allowed to quit first.', 0, 'short', 'long-distance,active', 'high'),
  ('Yoga side by side', 'A slow 30-minute yoga video on both screens, then lie there and talk.', 0, 'short', 'long-distance,active,chill', 'low'),
  ('Write a quiz about yourselves', 'Ten questions each about your own life. Take each other''s quiz, then the loser plans the next date.', 0, 'short', 'long-distance,games,romantic', 'low'),
  ('Two truths and a lie, deep edition', 'No easy ones: childhood, fears, secret talents. Explain each one after.', 0, 'short', 'long-distance,games', 'low'),
  ('Camera roll night', 'Scroll through each other''s photos from a year ago on a shared screen and tell the story behind five each.', 0, 'short', 'long-distance,romantic,cozy', 'low'),
  ('Read our first messages', 'Scroll back to where your chat began and read it aloud. Cringe allowed.', 0, 'short', 'long-distance,romantic', 'low'),
  ('Write a silly song together', 'One writes lyrics, the other finds a tune. Record a voice note of the result.', 0, 'short', 'long-distance,music,creative', 'med'),
  ('Duet karaoke online', 'A karaoke app with duets, or a lyrics video each and sing at the same time. Ballads only.', 0, 'short', 'long-distance,music,games', 'high'),
  ('Watch a concert together', 'A full live concert on YouTube, on both screens at the same moment. Dance if the song deserves it.', 0, 'short', 'long-distance,music', 'med'),
  ('Plant the same seeds', 'Buy the same seeds, plant them on a call, and send weekly photos to see whose grows faster.', 300, 'short', 'long-distance,creative,chill', 'low'),
  ('Write our bucket list', 'Fifty things to do together when you''re in the same city. Pin it somewhere you''ll both see.', 0, 'short', 'long-distance,romantic', 'low'),
  ('Street View holiday', 'Pick a city you both want to visit and walk it together in Street View. Choose where you''d stay.', 0, 'short', 'long-distance,adventurous,chill', 'low'),
  ('Cook a random country''s dish', 'Spin a globe app, both cook a dish from wherever it lands, then rate each other''s.', 800, 'short', 'long-distance,foodie,adventurous', 'med'),
  ('Online escape room for two', 'A digital escape room you can share a screen for. One reads clues, one solves.', 1000, 'short', 'long-distance,games,adventurous', 'high'),
  ('Build a Minecraft world together', 'Start a shared world and build a small house for the two of you, then keep adding to it.', 0, 'short', 'long-distance,games,creative', 'med'),
  ('Sunrise call', 'Set alarms, open the curtains and watch the sky change from both windows. Then go back to sleep.', 0, 'short', 'long-distance,romantic,chill', 'low'),
  ('Dress-up dinner on video', 'Dress like it''s a fancy restaurant, light a candle, eat the same meal. No pyjama bottoms.', 800, 'short', 'long-distance,romantic,foodie', 'low'),
  ('Teach each other one thing', 'Twenty minutes each: a card trick, a recipe, a song on guitar, a word in your language.', 0, 'short', 'long-distance,creative', 'med'),
  ('Listen to a shared playlist together', 'Make a shared or blended playlist, play it at the same moment and explain your picks.', 0, 'short', 'long-distance,music,chill', 'low'),
  ('A handwritten letter, read aloud', 'Write a real letter on paper, then read it to them on a call before you post it.', 100, 'short', 'long-distance,romantic', 'low'),
  ('Same takeaway, two cities', 'Order the same dish from a place in each city and rate them side by side. Each city defends its honour.', 1200, 'short', 'long-distance,foodie,games', 'low'),
  ('Daily puzzles together', 'Do the day''s word puzzles and crossword on a call, sharing hints and keeping score.', 0, 'short', 'long-distance,games,chill', 'low'),
  ('Redecorate a corner together', 'Show each other one corner of your room and fix it up on a call with what you already have.', 0, 'short', 'long-distance,creative', 'med'),
  ('Meditate together', 'A ten-minute guided meditation at the same time, then tell each other one thing you''re grateful for.', 0, 'short', 'long-distance,chill', 'low'),
  ('Record a podcast about us', 'Pick three questions, hit record on a call, and talk like guests on a show. Keep the file.', 0, 'short', 'long-distance,creative,games', 'med'),
  ('Shop for each other with ₹500', 'Each picks a small surprise gift online for the other, under ₹500. Unbox on a call when they arrive.', 1000, 'short', 'long-distance,romantic', 'low'),
  ('Watch a documentary and argue', 'Pick something neither of you knows about. Pause halfway for each of you to make a prediction.', 0, 'short', 'long-distance,cultural,chill', 'low'),
  ('Build the same LEGO set', 'Buy the same small set and build it on a call, step by step. First to finish waits.', 2000, 'short', 'long-distance,creative,games', 'low'),
  ('"Would you rather" marathon', 'Take turns asking, no skipping, and explain every answer.', 0, 'short', 'long-distance,games', 'low'),
  ('Make a video for us in a year', 'Record a few minutes each about now, then save it to open on this date next year.', 0, 'short', 'long-distance,romantic,creative', 'low')
)
INSERT INTO activities (title, notes, est_cost, setting, area, venue, lat, lng, duration, tags, energy, added_by, generated)
SELECT title, notes, est_cost, 'home', '', '', NULL, NULL, duration, tags, energy, 'joy', 1
FROM new WHERE NOT EXISTS (SELECT 1 FROM activities a WHERE a.title = new.title);
